CREATE TABLE IF NOT EXISTS company_sites
(
    id             SERIAL PRIMARY KEY,
    company_id     INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    site_name      VARCHAR(100) NOT NULL,
    pm2_5_value    NUMERIC(10, 2) NOT NULL,
    pm10_value     NUMERIC(10, 2) NOT NULL,
    latitude       NUMERIC(11, 8) NOT NULL,
    longitude      NUMERIC(11, 8) NOT NULL,
    created_at     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (company_id, site_name)
    );

-- Keep Ho Chi Minh City as one OpenAQ-backed station when this seed is re-run.
DELETE FROM company_sites
WHERE site_name LIKE 'Ho Chi Minh Ambient Station - %'
   OR site_name IN (
       'Ho Chi Minh OpenAQ Station - District 1',
       'Saigon Hi-Tech Park - FPT Lot 1',
       'Tan Thuan Export Processing Zone - REE Lot 1',
       'Cat Lai Logistics Zone - Vietnam National Petroleum Group Lot 1',
       'Vinhomes Central Park - Urban Operations'
   );

