    -- Single Ho Chi Minh City OpenAQ-backed monitoring site.
    ((SELECT id FROM companies WHERE company_name = 'Government Environmental Agency'), 'Ho Chi Minh OpenAQ Station - District 1', 0, 0, 10.776900, 106.700900),
